import type { Cefr, PlacementItem } from '../../../shared/types.js';
interface ReadingProbe { text: string; question: string; answer: string; distractors: [string, string, string]; explanation: string; subskill: string }
const p = (text: string, question: string, answer: string, distractors: [string, string, string], explanation: string, subskill = 'explicit-information'): ReadingProbe => ({ text, question, answer, distractors, explanation, subskill });

const a2: ReadingProbe[] = [
  p('The art room is closed this morning because workers are fixing a window. Your painting class will meet in Room 8, beside the office. Bring your own pencils. Brushes and paper will be on the tables when you arrive.', 'What should students bring to the changed class?', 'Their own pencils', ['Paper for the tables', 'A new window', 'Paintbrushes from home'], 'Thông báo ghi rõ “Bring your own pencils”; giấy và cọ đã được chuẩn bị.'),
  p('Mia takes an early bus to her new job. She buys breakfast near the office because the journey is long. On Fridays, she works from home and cooks breakfast with her sister before opening her computer.', 'When does Mia prepare breakfast at home?', 'On Fridays', ['Every workday', 'Before each bus journey', 'Only at weekends'], 'Đoạn văn nói cô làm tại nhà vào thứ Sáu và nấu bữa sáng với chị/em gái.'),
  p('Our pool has two entrances. Please use the entrance beside the car park if you have a pushchair. The front entrance has steps. Both doors open at seven, and staff can help you find the changing rooms inside.', 'Which entrance is suitable for a pushchair?', 'The one beside the car park', ['The front door with steps', 'A door in the changing room', 'Neither entrance before eight'], 'Lối cạnh bãi đỗ xe được chỉ định cho người có xe đẩy; cửa trước có bậc thang.'),
  p('Jon wants to buy a jacket for walking. He likes the blue one, but it has no pockets. He chooses a green jacket with large pockets because he often carries keys and a small map without taking a bag.', 'Why does Jon choose the green jacket?', 'It has useful pockets', ['It matches his blue bag', 'It costs less than a map', 'It is his favourite colour'], 'Lý do được nêu là túi lớn giúp mang chìa khóa và bản đồ mà không cần túi xách.'),
  p('The gardening club meets behind the school on Tuesday afternoons. New members do not need tools, but they should wear old clothes. The first meeting includes a walk around the garden, followed by planting seeds in small pots.', 'What should a new club member wear?', 'Old clothes', ['A school sports uniform', 'New gardening boots', 'A formal jacket'], 'Thông báo yêu cầu quần áo cũ; không yêu cầu đồng phục, giày mới hay đồ trang trọng.'),
  p('A parcel arrived while Rosa was at work. The driver left it at the shop downstairs, not with her neighbour. The shop closes at six today, so Rosa plans to collect the parcel during her lunch break.', 'Where can Rosa collect the parcel?', 'At the downstairs shop', ['At her neighbour’s flat', 'At the delivery office', 'At her workplace'], 'Người giao để hàng tại cửa hàng tầng dưới; các nơi còn lại không phải điểm nhận.'),
  p('Please put returned books on the trolley near the desk. Do not place them on the shelves yourself. A librarian must check each book first. You may still choose new books while your returned ones are being checked.', 'Where should a visitor leave returned books?', 'On the trolley near the desk', ['On any empty shelf', 'Beside the entrance outside', 'In a bag with new books'], 'Hướng dẫn yêu cầu để sách trên xe đẩy gần bàn để thủ thư kiểm tra trước.'),
  p('Leo used to walk to football practice, but the club now uses a field farther away. He travels there with his cousin by bicycle. They leave early because they enjoy a short rest before the practice begins.', 'How does Leo reach the new football field?', 'By bicycle with his cousin', ['On foot with his coach', 'By bus on his own', 'In a car after practice starts'], 'Đoạn văn ghi anh và anh họ đi xe đạp tới sân mới.'),
  p('The café serves soup until two in the afternoon. Sandwiches are available until closing time at five. Today the soup is vegetable soup, and every bowl comes with bread. You can eat inside or take your food away.', 'What can a customer still buy at three?', 'A sandwich', ['A bowl of vegetable soup', 'Only bread with soup', 'Nothing because the café is closed'], 'Súp chỉ bán đến 14 giờ; sandwich được bán đến khi đóng cửa lúc 17 giờ.'),
  p('Nina keeps a small notebook in her bag. She writes down new English words on the bus and checks them at home. She does not write during lessons because she prefers listening carefully to the teacher at that time.', 'When does Nina check the words she has recorded?', 'At home', ['While the teacher is speaking', 'Before getting on the bus', 'At the bus station every morning'], 'Cô ghi từ trên xe buýt và kiểm tra chúng tại nhà; trong tiết học cô ưu tiên nghe.'),
  p('The morning walking group will start at the museum door tomorrow. The usual meeting place in the park is too wet after the rain. The walk will still finish at the park café, where hot drinks are available.', 'What has changed for tomorrow’s walk?', 'The starting place', ['The café at the end', 'The availability of hot drinks', 'The name of the museum'], 'Điểm bắt đầu chuyển từ công viên sang cửa bảo tàng; điểm kết thúc vẫn là quán trong công viên.'),
  p('Sam has three shelves for his plants. The plants that need the most sun are on the top shelf. He keeps the others lower down, away from the window. He checks the soil each morning before deciding which plants need water.', 'Where does Sam keep plants that need strong sunlight?', 'On the top shelf', ['On the lowest shelf', 'In a room without windows', 'Under all the other plants'], 'Những cây cần nhiều nắng được đặt ở kệ trên cùng.'),
  p('Tickets for the school concert are sold at the office, not at the hall. The office accepts cash only. If you cannot visit during the day, ask a student to collect a ticket for you before Thursday afternoon.', 'How can someone buy a concert ticket?', 'Pay cash at the school office', ['Pay by card inside the hall', 'Buy it online after Thursday', 'Send payment to a performer'], 'Vé bán tại văn phòng và chỉ nhận tiền mặt; không bán ở hội trường.'),
  p('This bag belongs to the cooking class. It contains clean aprons for today’s learners. Please choose one before entering the kitchen, then put it in the marked basket after the class. Staff will wash the aprons later.', 'What should learners do with an apron after class?', 'Put it in the marked basket', ['Take it home to wash', 'Leave it on a kitchen table', 'Return it to the clean-apron bag'], 'Sau lớp, tạp dề được bỏ vào giỏ đánh dấu để nhân viên giặt.'),
  p('Ella enjoys taking photographs, but her phone has very little free space. She moves useful pictures to her computer every Sunday. She deletes blurred ones immediately, so she does not have to check them again when she sorts the weekly photos.', 'Which photographs does Ella remove straight away?', 'The blurred ones', ['All pictures from Sunday', 'The useful ones on her computer', 'Only photographs of her phone'], 'Cô xóa ảnh mờ ngay; những ảnh hữu ích được chuyển sang máy tính mỗi Chủ nhật.'),
  p('The baker usually delivers bread to this shop at eight. Today the van has a problem, so fresh bread will arrive at ten instead. You can still buy yesterday’s bread at half price while waiting for the delivery.', 'Why will fresh bread arrive later today?', 'There is a problem with the van', ['The shop opens two hours late', 'The baker has no flour', 'Customers ordered too much bread'], 'Thông báo nêu xe giao hàng gặp trục trặc, vì vậy bánh tươi tới lúc 10 giờ.'),
  p('Arun joined a music group last month. He already plays the guitar, but the group needs a drummer, so he is learning drums too. A friend lends him some equipment until he can decide whether to buy his own.', 'Why is Arun learning to play drums?', 'The group needs a drummer', ['He has stopped liking the guitar', 'He already bought new drums', 'His friend cannot play any instrument'], 'Anh học trống vì ban nhạc cần người đánh trống, không phải vì bỏ guitar.'),
  p('Visitors may leave coats in the cupboard near reception. Please keep money and phones with you because the cupboard is not locked. Large suitcases should stay in the separate luggage room, where staff will give you a numbered ticket.', 'Which items should visitors keep with them?', 'Money and phones', ['All coats and suitcases', 'Only numbered luggage tickets', 'The reception cupboard key'], 'Khách được nhắc giữ tiền và điện thoại vì tủ áo không khóa.'),
  p('The science club’s trip to the lake costs twelve pounds. This includes the bus journey and a guide, but not lunch. Bring food from home because the lake café is closed on the day of our visit.', 'What is not included in the trip price?', 'Lunch', ['The bus journey', 'The guide', 'Travel to the lake'], 'Giá bao gồm xe buýt và hướng dẫn viên, nhưng không gồm bữa trưa.'),
  p('Kim studies in the library twice a week. She likes a desk near the back because it is quieter there. When she works with classmates on a project, she books a group room so their conversation does not disturb other readers.', 'Where does Kim work on a shared project?', 'In a booked group room', ['At her usual quiet desk', 'Near the library entrance', 'Outside with all other readers'], 'Khi làm dự án cùng bạn, cô đặt phòng nhóm để cuộc trò chuyện không làm phiền người đọc.'),
  p('Please collect your repaired bicycle before Saturday. The workshop will close for a week while the owner visits family. If you cannot collect it in time, phone us today so we can arrange a safe place to keep it.', 'What should a customer do if collection before Saturday is impossible?', 'Phone the workshop today', ['Leave the bicycle outside the shop', 'Collect it during the closure', 'Wait until Saturday to call'], 'Thông báo yêu cầu gọi hôm nay để sắp xếp nơi giữ xe an toàn.'),
  p('Ben made a shopping list but left it on the kitchen table. At the supermarket, he remembers the vegetables but forgets the rice. He calls his flatmate, who reads the list to him before he reaches the checkout.', 'How does Ben find out what he forgot?', 'His flatmate reads the list by phone', ['He returns home before shopping', 'A cashier finds his notebook', 'He reads a photo he took earlier'], 'Bạn cùng nhà đọc danh sách qua điện thoại trước khi anh tới quầy thanh toán.'),
  p('The new playground opens on Monday. Children can use the climbing frame and swings, but the sand area is not ready yet. Work there will finish next month. Adults should stay with young children throughout their visit.', 'Which part cannot be used when the playground opens?', 'The sand area', ['The swings', 'The climbing frame', 'All parts until next month'], 'Khu cát chưa sẵn sàng; leo trèo và xích đu được sử dụng từ ngày mở cửa.'),
  p('Lena’s train leaves at nine, and the station is a twenty-minute walk from home. She wants to arrive half an hour early to buy a ticket. She therefore plans to leave home at ten past eight tomorrow morning.', 'Why does Lena leave home before eight thirty?', 'She wants time to buy a ticket', ['The walk takes an hour', 'The train leaves before nine', 'The ticket office is at her house'], 'Cô cần tới sớm 30 phút để mua vé, cộng thêm 20 phút đi bộ.'),
  p('The flower shop has received more yellow roses than usual. They are cheaper today, but the price of white roses has not changed. Customers who buy six yellow roses will receive a free paper bag to carry them home.', 'Which flowers are cheaper today?', 'Yellow roses', ['White roses', 'All flowers in the shop', 'Only flowers without paper bags'], 'Chỉ hoa hồng vàng được giảm giá; giá hoa trắng không thay đổi.'),
  p('Omar wants to read more during his lunch break. He chooses short stories because he can often finish one before returning to work. He leaves longer novels at home, where he has more time in the evening.', 'Why does Omar choose short stories for lunchtime?', 'He can finish one within the break', ['He dislikes reading at home', 'His workplace sells only short books', 'He has no books for the evening'], 'Truyện ngắn phù hợp độ dài giờ nghỉ và thường đọc xong trước khi trở lại làm việc.'),
  p('Please keep the side gate closed. The garden is open to visitors, but our dog must not leave the property. You may walk around the flower beds and sit on the bench. Do not open the small greenhouse without asking first.', 'Why must the side gate remain closed?', 'To stop the dog leaving', ['To prevent all visitors entering', 'To keep flowers out of the greenhouse', 'To reserve the bench for staff'], 'Cổng cần đóng để chó không ra khỏi khu đất; vườn vẫn mở cho khách.'),
  p('A customer left a red umbrella in the café yesterday. It is now behind the counter. If it is yours, tell a staff member where you were sitting. We will keep it for two weeks before giving unclaimed items away.', 'How can the umbrella’s owner identify it to staff?', 'Say where they were sitting', ['Describe the café’s opening hours', 'Wait until two weeks have passed', 'Show a receipt for a new umbrella'], 'Chủ ô được yêu cầu nói vị trí đã ngồi; không cần mua ô mới hay đợi hai tuần.'),
  p('Tara’s apartment has a small balcony. She grows herbs there, not large vegetables, because the containers are shallow. She uses the herbs when cooking and sometimes gives a little to the neighbour who helps water them during her holidays.', 'Why does Tara choose herbs for her balcony?', 'Her containers are shallow', ['She never cooks vegetables', 'The neighbour owns the balcony', 'She only grows plants while on holiday'], 'Cô chọn rau thơm vì chậu nông, không thích hợp trồng rau lớn.'),
  p('The meeting is still on Wednesday, but it will begin fifteen minutes later than planned. Please arrive at the usual room at three fifteen. Bring the draft timetable you received yesterday so everyone can suggest changes during the discussion.', 'What has changed about the meeting?', 'Its starting time', ['Its day', 'Its room', 'Its discussion topic'], 'Cuộc họp vẫn vào thứ Tư, cùng phòng, nhưng bắt đầu muộn hơn 15 phút.'),
  p('Alex visits his grandparents every other Sunday. They live near a river, and they usually walk there together before lunch. If it rains, they play a board game indoors. His grandmother always prepares something warm for them to eat afterwards.', 'What do they do when the weather is wet?', 'Play a game inside', ['Walk farther along the river', 'Cancel lunch completely', 'Visit only on Saturdays'], 'Khi mưa, cả nhà chơi board game trong nhà thay vì đi dạo ven sông.'),
  p('The repair shop can replace a phone screen in one day, but changing a battery takes longer because parts must be ordered. Please bring your charger when asking us to check a charging problem. We will explain the cost before starting work.', 'What should a customer bring for a charging check?', 'Their phone charger', ['A new battery already fitted', 'An order for a replacement screen', 'Payment before receiving a price'], 'Khách cần mang bộ sạc để kiểm tra lỗi sạc; giá được giải thích trước khi làm.'),
  p('At the open day, the kitchen tour starts every hour. Places are limited, so book at reception when you arrive. The garden can be visited without a booking, and the exhibition in the hall remains open all afternoon.', 'Which activity requires a booking?', 'The kitchen tour', ['Walking in the garden', 'Viewing the hall exhibition', 'All afternoon activities'], 'Tour bếp cần đăng ký tại lễ tân; vườn và triển lãm không yêu cầu đăng ký.'),
  p('Priya has started keeping her keys in a bowl by the door. She used to leave them in different coat pockets and often spent time searching. The bowl is bright blue, which helps her notice it even when the hallway is dark.', 'What problem does Priya’s new habit address?', 'Difficulty finding her keys', ['Not having enough coats', 'Losing the hallway light', 'Choosing a colour for the door'], 'Đặt chìa khóa tại một chỗ giúp tránh mất thời gian tìm trong nhiều túi áo.'),
  p('The community centre is offering a free writing session for adults. You do not need experience or a computer. There will be paper and pens in the room. Please phone to reserve a place because the group will be small.', 'What must someone do before attending?', 'Reserve a place by phone', ['Buy a computer', 'Show previous writing experience', 'Bring payment for the session'], 'Buổi học miễn phí, có giấy bút, nhưng cần gọi điện đặt chỗ.'),
  p('The lift in this building is being repaired until Friday. Staff will move appointments for visitors who cannot use the stairs to the ground floor. Please contact the office before your visit if you need this arrangement.', 'What help is available while the lift is broken?', 'A ground-floor appointment', ['A repaired lift before Friday', 'A staff member carrying every visitor', 'All appointments being cancelled'], 'Người không đi cầu thang được có thể được chuyển lịch hẹn xuống tầng trệt khi báo trước.'),
  p('Daniel borrowed a tent for a weekend trip. Before returning it, he opened it in the garden so it could dry. He checked that all the poles were present and then packed everything into the bag with a thank-you note.', 'Why did Daniel open the tent after the trip?', 'To let it dry', ['To count the thank-you notes', 'To use it for another holiday', 'To avoid returning the poles'], 'Anh mở lều trong vườn để làm khô trước khi trả lại.'),
  p('The museum’s family tickets cover two adults and up to three children. They can be used on any day except special evening events. Audio guides cost extra, but printed activity sheets for children are included in the ticket price.', 'What is included with a family ticket?', 'Children’s printed activity sheets', ['Audio guides for everyone', 'Every special evening event', 'Admission for four adults'], 'Phiếu hoạt động in cho trẻ em nằm trong giá vé; audio guide tính thêm.'),
  p('Sara bought a notebook with plain pages for sketching. She already had a lined notebook for class notes, but the lines made drawing large shapes difficult. She keeps the two books in different parts of her bag to find them quickly.', 'Why did Sara buy a notebook with plain pages?', 'Lines made sketching difficult', ['She had stopped taking class notes', 'Her old book had no pages left', 'Plain pages were required for every lesson'], 'Cô mua giấy trắng vì đường kẻ gây khó vẽ hình lớn; vẫn giữ vở ghi bài riêng.'),
  p('The bus stop outside the hospital is temporarily closed. For buses towards the station, use the stop beside the bakery. Buses going the other way still stop across the road. Normal service at the hospital stop will return next week.', 'Where should a passenger going to the station wait?', 'Beside the bakery', ['Across the road for the opposite direction', 'At the closed hospital stop', 'Inside the station next week'], 'Hành khách đi hướng nhà ga phải dùng điểm cạnh tiệm bánh trong thời gian đóng điểm cũ.'),
];

const b1: ReadingProbe[] = [
  p('The school has moved its parents’ meeting online this month. Several families said that travelling to the building after work was difficult. Parents who do not have suitable internet access may use a computer in the school office, where a staff member will help them join the same meeting.', 'Why has the school provided a computer in its office?', 'To let families without suitable internet join', ['To stop parents attending from home', 'To hold a different meeting for staff', 'To teach every parent computer repair'], 'Máy tại văn phòng hỗ trợ gia đình thiếu kết nối phù hợp tham gia cùng cuộc họp.', 'purpose-and-paraphrase'),
  p('A cycling group originally planned to ride forty kilometres on Sunday. After checking the forecast, the organiser shortened the route and added a stop under shelter. The group still expects to go ahead, but members are asked to bring warm clothing because the temperature may fall during the afternoon.', 'How has the organiser responded to the forecast?', 'Adjusted the ride instead of cancelling it', ['Kept every part of the original plan', 'Required members to cycle farther', 'Moved the event entirely indoors'], 'Tuyến được rút ngắn và thêm điểm trú; hoạt động vẫn diễn ra, không bị hủy.', 'purpose-and-paraphrase'),
  p('When a local bookshop began a delivery service, staff assumed most customers would order popular novels. Instead, many requests were for children’s school books and large-print editions. The owner now keeps a better stock of those titles, while still asking customers what they would like to see on the shelves.', 'What led the owner to change the stock?', 'The kinds of books customers actually requested', ['A rule against selling popular novels', 'The closure of every nearby school', 'A decision to stop asking customers questions'], 'Nhu cầu thực tế khác dự đoán: sách học và chữ lớn khiến chủ điều chỉnh hàng.', 'purpose-and-paraphrase'),
  p('Jo began learning guitar from videos but struggled to notice her own mistakes. She booked a short lesson with a teacher, who changed the position of her left hand and suggested slower practice. She still uses videos for new songs, but now checks that she can play each section accurately before increasing speed.', 'What did Jo gain from the individual lesson?', 'Feedback on a problem she had not identified', ['A reason to abandon all online resources', 'Permission to avoid practising slowly', 'A guarantee of becoming a professional'], 'Giáo viên sửa vị trí tay, vấn đề cô không tự nhận ra khi chỉ học video.', 'purpose-and-paraphrase'),
  p('The council’s trial recycling point was busy, but several people left materials that it could not accept. Staff added pictures showing suitable items and placed a separate information board near the entrance. They will review the results next month before deciding whether another collection point is needed.', 'What problem are the new pictures intended to address?', 'People bringing unsuitable materials', ['A lack of visitors to the site', 'A decision already made to close the point', 'Staff being unable to find the entrance'], 'Hình minh họa làm rõ vật liệu được nhận sau khi khách bỏ nhầm nhiều đồ.', 'purpose-and-paraphrase'),
  p('A museum volunteer noticed that visitors often walked past a small display of workers’ tools. She began offering a two-minute explanation using one tool as an example. More people then looked closely at the display, even though the objects and their position had not changed.', 'What made the display attract more attention?', 'A short explanation connecting visitors with an object', ['Moving all the tools to a new room', 'Replacing the tools with modern equipment', 'Extending every visit by several hours'], 'Vị trí và hiện vật giữ nguyên; lời giải thích ngắn khiến khách quan sát kỹ hơn.', 'purpose-and-paraphrase'),
  p('The café owner wanted to reduce leftovers without making customers feel rushed. She began offering a smaller lunch portion alongside the usual one. Customers can still order extra bread if needed. After the first week, less food returned to the kitchen, while the number of meals sold stayed similar.', 'What does the first week suggest about the smaller portion?', 'It may reduce waste without reducing meal sales', ['It has made customers stop buying lunch', 'It prevents anyone from ordering extra food', 'It has proved all waste comes from bread'], 'Thức ăn dư giảm trong khi số bữa bán tương tự; chỉ là kết quả ban đầu, không chứng minh mọi nguyên nhân.', 'purpose-and-paraphrase'),
  p('Dina’s new job is closer to home, but she has chosen not to drive. The bus takes ten minutes longer than a car journey, yet it leaves her free to read and avoids the cost of parking. She says the extra time is acceptable because the service is usually reliable.', 'Why is Dina willing to accept a longer journey?', 'The bus offers benefits that matter to her', ['She thinks the bus is always faster', 'Her employer has banned car travel', 'Parking is free only for bus passengers'], 'Cô chấp nhận thêm thời gian để được đọc sách và tránh phí đỗ, với dịch vụ khá ổn định.', 'purpose-and-paraphrase'),
  p('A language class asks learners to keep one recording from each month. They listen to an older recording before making a new one and write down a specific difference. The teacher explains that the aim is not to compare classmates but to notice changes that may be difficult to hear from day to day.', 'What is the main purpose of keeping the recordings?', 'To help learners recognise their own progress', ['To rank students against one another', 'To replace speaking practice with writing', 'To find the single best monthly speaker'], 'Bản ghi giúp người học nhận tiến bộ của chính mình, thay vì xếp hạng bạn học.', 'purpose-and-paraphrase'),
  p('The walking guide does not list every interesting building along the route. Its author selected a few places where a short story helps explain the area’s development. Readers are encouraged to explore other streets afterwards, rather than feel they have finished learning about the town by completing the route.', 'Why does the guide include only selected buildings?', 'They provide useful examples for understanding the area', ['The author believes no other buildings matter', 'Readers are forbidden to leave the route', 'The town has only a few buildings left'], 'Các điểm được chọn để minh họa phát triển của khu vực; tác giả vẫn khuyến khích khám phá thêm.', 'purpose-and-paraphrase'),
  p('Tessa offered to organise a neighbourhood meal, then realised that choosing food for everyone alone would be difficult. She asked each household to bring a dish and write its ingredients on a card. The shared meal became easier to arrange, and guests could check what they were eating without asking every cook.', 'What advantage did the ingredient cards provide?', 'Guests could identify what was in each dish', ['Every household had to cook the same food', 'Tessa no longer needed any tables', 'The cards guaranteed everyone liked each dish'], 'Thẻ nguyên liệu giúp khách biết thành phần mà không phải hỏi từng người nấu.', 'purpose-and-paraphrase'),
  p('A repair shop gives customers a price estimate before opening damaged equipment. The final cost may change if a hidden fault is found, but staff will contact the customer before continuing. The owner introduced this rule after people complained that they had agreed to one repair and received a much larger bill.', 'Why must staff contact the customer about an extra fault?', 'To obtain agreement before adding repair costs', ['To promise the original estimate can never change', 'To ask customers to repair the fault themselves', 'To avoid explaining the final bill'], 'Quy định bảo đảm khách đồng ý trước khi tiếp tục công việc làm tăng chi phí.', 'purpose-and-paraphrase'),
  p('The evening pottery course has no final competition. Learners choose a useful object, test different methods and explain one change they made after a problem. The instructor says a neat finished piece is welcome, but understanding the material matters more than producing the most attractive object in the room.', 'What does the instructor value most?', 'Learning how to work with the material', ['Winning against the other learners', 'Making every object look identical', 'Avoiding any changes after a mistake'], 'Mục tiêu chính là hiểu vật liệu và điều chỉnh cách làm, không phải thi đẹp nhất.', 'purpose-and-paraphrase'),
  p('The sports centre had many visitors on Saturday but very few on weekday mornings. It offered a reduced morning fee and a beginner session, then asked new users what had encouraged them to attend. Some mentioned the price, while others said knowing the class welcomed beginners was more important.', 'What did the responses show?', 'Different users were encouraged by different features', ['Lower prices were the only factor for everyone', 'The beginner session attracted no new visitors', 'Saturday attendance had become impossible'], 'Một số người chú ý giá, người khác chú ý sự chào đón người mới; không có một lý do duy nhất.', 'purpose-and-paraphrase'),
  p('Theo’s family uses a shared calendar for appointments, but they do not record every personal activity. The calendar is mainly for events that affect someone else, such as needing a lift or using the car. Theo says this keeps it useful without making family members feel that every hour must be explained.', 'What determines whether an event goes on the calendar?', 'Whether it affects another family member', ['Whether it lasts longer than one hour', 'Whether every relative attends it', 'Whether it is part of someone’s private routine'], 'Lịch chung tập trung vào việc ảnh hưởng người khác, như dùng xe hoặc cần đưa đón.', 'purpose-and-paraphrase'),
  p('The exhibition includes an audio version of each main label. Visitors can choose either format, and headphones are available at reception. The curator explains that the recordings are not intended to replace written information; they provide another way to access the same content for people with different needs.', 'What is the reason for providing audio labels?', 'To offer an alternative way to access information', ['To remove every written label', 'To make the exhibits change throughout the day', 'To require all visitors to wear headphones'], 'Audio là lựa chọn bổ sung cùng nội dung, không thay thế hoàn toàn chữ viết.', 'purpose-and-paraphrase'),
  p('A school garden grew fewer vegetables than expected because several young plants dried out during a holiday. The next term, pupils created a watering rota with adult supervision. They also chose some plants that needed less frequent watering, instead of assuming that a longer list of helpers would solve the entire problem.', 'How did the pupils respond to the poor harvest?', 'Changed both care arrangements and plant choices', ['Stopped growing all vegetables permanently', 'Decided that supervision was unnecessary', 'Kept the same plants without changing watering'], 'Họ lập lịch tưới và đổi sang cây ít cần nước hơn, nên giải pháp gồm hai phần.', 'purpose-and-paraphrase'),
  p('The new bus timetable is printed on a larger board at the stop. A simple map beside it shows where passengers can change routes. The transport office made these changes after first-time users said they could read departure times but did not understand how the routes connected.', 'What need does the added map address?', 'Understanding connections between routes', ['Finding the bus driver’s home', 'Reading prices that have not been printed', 'Changing every departure time'], 'Người mới khó hiểu các tuyến nối nhau thế nào, dù đã đọc giờ chạy; bản đồ giải quyết điều đó.', 'purpose-and-paraphrase'),
  p('Nora joined an online reading group because travelling to evening meetings was difficult. She likes the discussion but misses the informal conversation that happened before local meetings. The organiser has now left the online room open for ten extra minutes at the end so anyone who wants to stay can chat.', 'Why does the organiser keep the room open longer?', 'To allow informal conversation after the discussion', ['To force every member to read another chapter', 'To replace the discussion with a lecture', 'To move all meetings back to a local building'], 'Mười phút thêm dành cho trò chuyện tự do, bù phần giao lưu cô thấy thiếu.', 'purpose-and-paraphrase'),
  p('A shop’s website shows whether an item is in stock, but the owner asks customers to reserve it before making a long journey. Another customer may buy the last one before they arrive. Reserving does not require payment immediately; it simply means staff will keep the item until the agreed time.', 'What is the purpose of reserving an item?', 'To ensure it remains available for the visit', ['To pay the full price before checking it', 'To stop the website showing any stock', 'To arrange an automatic home delivery'], 'Đặt giữ tránh người khác mua món cuối trước khi khách tới; không bắt buộc trả ngay.', 'purpose-and-paraphrase'),
  p('After moving house, Eli kept taking the familiar route to work even though it was no longer the shortest. A colleague showed him a quieter street with a direct pedestrian crossing. He now uses that route in daylight, but chooses the busier road after dark because the quieter street has poor lighting.', 'Why does Eli sometimes keep using the busier road?', 'It is a more suitable choice after dark', ['It is always the shortest route', 'The pedestrian crossing works only for colleagues', 'He has forgotten the quieter street'], 'Đường yên tĩnh thiếu ánh sáng nên buổi tối anh chọn đường đông hơn, dù ban ngày đi lối mới.', 'purpose-and-paraphrase'),
  p('The college café has put water jugs on a side table. Customers may refill their bottles without buying a meal. Staff introduced the table to reduce the number of disposable bottles used during the day. They still sell bottled drinks for people who prefer them or need to take a sealed drink away.', 'What does the new table allow?', 'Free bottle refills without a food purchase', ['Only meal buyers to obtain water', 'A complete ban on bottled drinks', 'Customers to take all the jugs home'], 'Khách có thể châm nước mà không phải mua bữa ăn; nước đóng chai vẫn bán.', 'purpose-and-paraphrase'),
  p('A tour company offers a shorter route for visitors who cannot walk far. The guide covers fewer sites but spends more time explaining each one. The company does not describe it as a less complete experience; it is designed for people who value a slower pace and accessible paths.', 'How does the shorter tour differ?', 'Fewer sites receive more explanation', ['It has no guide or historical information', 'It is intended only for faster walkers', 'It covers more sites in less time'], 'Tuyến ngắn có ít điểm hơn nhưng dành nhiều thời gian giải thích mỗi điểm.', 'purpose-and-paraphrase'),
  p('Pavel was disappointed when his first public talk attracted only a small audience. A friend suggested asking those listeners what they found useful. Their comments showed that the practical examples were strong but the title had not explained the topic clearly. He changed the title before advertising the next talk.', 'What did feedback help Pavel improve?', 'How the talk was described to potential listeners', ['The number of chairs he owned', 'Every practical example in the talk', 'His decision to stop speaking publicly'], 'Ví dụ đã tốt nhưng tiêu đề chưa rõ; phản hồi giúp cải thiện cách quảng bá nội dung.', 'purpose-and-paraphrase'),
  p('The building’s shared washing machine is busiest on Sunday evening. Residents agreed to book short slots and leave enough time to remove clothes afterwards. The system does not give priority to one household. Anyone who needs an unusual time can ask others to swap rather than simply taking a longer slot.', 'What is the main aim of the booking agreement?', 'To make shared use predictable and fair', ['To reserve Sundays for one household', 'To prevent residents washing during the week', 'To let anyone ignore their booked ending time'], 'Lịch ngắn và quy định lấy đồ giúp mọi người sử dụng công bằng, dễ dự đoán.', 'purpose-and-paraphrase'),
  p('A museum shop has stopped wrapping every purchase automatically. Staff now ask whether wrapping is needed, especially for gifts. Many customers carrying items home in their own bags decline it. The shop still protects fragile objects, because reducing packaging is not useful if more products are damaged during the journey.', 'Why does the shop still protect fragile items?', 'Damage would undermine the benefit of less packaging', ['Every customer wants a gift wrapped', 'Fragile items cannot be carried in bags', 'The shop has abandoned its packaging policy'], 'Giảm bao bì không có ích nếu làm hỏng đồ; chính sách vẫn cân nhắc bảo vệ vật dễ vỡ.', 'purpose-and-paraphrase'),
  p('The community choir does not require new members to read music. The director teaches short sections by listening and repetition, then provides written notes for anyone who wants them. Some experienced singers help beginners quietly, but nobody is asked to perform alone during the first few sessions.', 'What can a beginner infer about joining the choir?', 'Lack of music-reading skill is not a barrier', ['Solo performance is required immediately', 'Written notes are forbidden for everyone', 'Only experienced singers may attend'], 'Không bắt buộc đọc nhạc, có cách dạy qua nghe và không yêu cầu hát solo lúc đầu.', 'purpose-and-paraphrase'),
  p('A new park path follows the river but closes during high water. Signs at both ends explain the alternative route through the town. The council says keeping the riverside path open in every condition would require expensive barriers and could damage the natural bank, so occasional closure is part of the design.', 'Why is occasional closure accepted?', 'Permanent protection would have cost and environmental drawbacks', ['The town route is closed all year', 'The river never rises above the path', 'The council forgot to consider high water'], 'Mở đường mọi lúc đòi rào chắn tốn kém, có thể hại bờ tự nhiên; đóng tạm là chủ ý.', 'purpose-and-paraphrase'),
  p('Faye checks a product review’s date before relying on it. She once bought software after reading an old recommendation and discovered that the current version had different features. She still finds reviews helpful, but now compares recent accounts and the maker’s description before deciding.', 'What lesson has Faye applied to later purchases?', 'Check that information describes the current version', ['Assume every review is deliberately false', 'Ignore the maker’s product information', 'Buy only the oldest version of software'], 'Trải nghiệm cho thấy đánh giá cũ có thể không áp dụng phiên bản hiện tại, nên cần kiểm tra thời điểm.', 'purpose-and-paraphrase'),
  p('The school’s lost-property table will be available after classes this week. Parents are asked to look even if their child has not reported losing anything. Staff have found many unlabelled coats, and children sometimes forget that a missing item belongs to them until they see it again.', 'Why are all parents encouraged to check the table?', 'Children may not remember that an item is missing', ['Every child has definitely lost a coat', 'Staff cannot open the table after lessons', 'Only labelled clothing will be displayed'], 'Trẻ có thể quên món đã mất cho tới khi nhìn thấy; lời mời không khẳng định mọi trẻ đều mất áo.', 'purpose-and-paraphrase'),
  p('The cooking instructor demonstrates a recipe with a common vegetable and then suggests several alternatives. Learners are not expected to buy the exact same ingredients afterwards. She wants them to understand the method well enough to use what is available locally and avoid leaving unfamiliar ingredients unused.', 'What does the instructor want learners to understand?', 'A method that can work with suitable alternatives', ['The need to buy every demonstrated ingredient', 'Why local vegetables should be avoided', 'How to make every dish taste identical'], 'Cô dạy phương pháp linh hoạt với nguyên liệu địa phương, không bắt mua đúng mọi món.', 'purpose-and-paraphrase'),
  p('The library’s Saturday film session begins with a brief introduction, not a full explanation of the ending. After the film, visitors may stay for a discussion. The organiser says people should have time to form their own impressions before hearing detailed interpretations from others.', 'Why is the opening introduction brief?', 'To avoid shaping viewers’ opinions too strongly beforehand', ['To prevent anyone learning the film’s name', 'To ensure no discussion takes place later', 'To finish the film before visitors arrive'], 'Giới thiệu ngắn để người xem hình thành cảm nhận riêng trước khi nghe phân tích chi tiết.', 'purpose-and-paraphrase'),
  p('A workplace stopped sending routine messages late at night. Urgent issues still use a separate contact system, but ordinary updates are scheduled for the next morning. Staff had said that even messages requiring no immediate answer made it difficult to feel fully away from work.', 'What problem is the change intended to reduce?', 'Difficulty separating free time from routine work communication', ['The absence of any emergency contact method', 'Staff refusing to read morning updates', 'A need for all employees to work at night'], 'Tin thường gửi khuya làm khó tách giờ riêng khỏi công việc; kênh khẩn cấp vẫn tồn tại.', 'purpose-and-paraphrase'),
  p('A local festival moved its information desk away from the main stage. Visitors had struggled to hear directions over the music. The new desk is less visible from the entrance, so large signs now point towards it. Organisers will ask visitors whether the quieter position makes finding help easier overall.', 'What trade-off did organisers have to address?', 'A quieter desk was less immediately visible', ['A larger stage made all signs unnecessary', 'Moving the desk removed the need for directions', 'Visitors could hear better only beside the music'], 'Vị trí mới yên tĩnh nhưng khó thấy từ lối vào, nên cần biển chỉ lớn.', 'purpose-and-paraphrase'),
  p('Tomas joined a beginner running group but found its distance too demanding. The coach suggested alternating running and walking rather than leaving the group completely. After several weeks, he could run for longer periods. He says the flexible approach kept him involved without pretending he had the same starting ability as everyone else.', 'Why did the coach suggest a mixed running-and-walking approach?', 'To make continued participation realistic for Tomas', ['To stop him attending future sessions', 'To prove all beginners have identical fitness', 'To replace the group’s activity with sightseeing'], 'Cách xen kẽ giúp anh tiếp tục theo khả năng hiện tại thay vì bỏ nhóm hoặc cố bằng mọi người.', 'purpose-and-paraphrase'),
  p('The town’s volunteer gardeners meet regularly, but not everyone can attend each session. They now leave a short note describing completed work and the next priority. This prevents one group repeating another’s task and allows occasional volunteers to contribute without needing a long explanation every time.', 'What benefit does the shared note provide?', 'It helps different volunteers coordinate their work', ['It requires every volunteer to attend weekly', 'It replaces all gardening tools', 'It lets people avoid checking completed tasks'], 'Ghi chú việc đã làm và ưu tiên tới giúp nhóm khác tránh làm trùng và dễ tham gia.', 'purpose-and-paraphrase'),
  p('A guesthouse provides a small map of nearby walking routes, but it does not describe them all as easy. Each route includes distance, surface and steep sections. The owner wants guests to choose according to their own needs rather than assume that the shortest route is suitable for every visitor.', 'Why does the map describe surfaces and steep sections?', 'Distance alone does not show whether a route suits someone', ['All short walks are more difficult than long ones', 'Guests must complete every listed route', 'The owner wants to discourage all walking'], 'Độ dài không đủ đánh giá phù hợp; mặt đường và dốc ảnh hưởng nhu cầu mỗi người.', 'purpose-and-paraphrase'),
  p('Leah wanted to clear her cupboard quickly and considered giving away all her old notebooks. Before doing so, she checked them and found useful records from a project she might repeat. She kept those pages in one folder, then recycled the remaining paper instead of keeping every book unchanged.', 'How did Leah balance space and useful information?', 'Saved selected records rather than all the notebooks', ['Kept every notebook without checking it', 'Destroyed all records from the project', 'Bought a larger cupboard for the same books'], 'Cô giữ các trang hữu ích trong một tập và tái chế phần còn lại, không giữ nguyên tất cả.', 'purpose-and-paraphrase'),
  p('The new train ticket machine offers several language options, but staff remain nearby to answer questions. During the trial, some passengers understood the translated words yet were unsure which ticket matched their journey. The station manager says improving labels does not remove the need for help with unfamiliar choices.', 'What did the trial reveal?', 'Translation alone did not resolve every ticketing difficulty', ['No passenger could read any language option', 'Staff assistance made translated words unnecessary', 'Every journey required the same ticket'], 'Khách hiểu từ dịch nhưng vẫn khó chọn loại vé; ngôn ngữ rõ chưa giải quyết hết sự không quen.', 'purpose-and-paraphrase'),
  p('A school club records the birds seen in its garden each week. Pupils are told to write “unknown” if they are unsure rather than choose a species that looks similar. The teacher explains that an honest gap in the record is more useful than a confident guess that may later be treated as fact.', 'Why are pupils allowed to record “unknown”?', 'To avoid turning uncertain guesses into false information', ['To show that identifying birds is impossible', 'To make every weekly record identical', 'To prevent pupils observing unfamiliar birds'], 'Ghi “unknown” giữ sự trung thực khi chưa chắc, tránh biến phỏng đoán thành dữ kiện sai.', 'purpose-and-paraphrase'),
];
const b2: ReadingProbe[] = [
  p('A study found that residents who used a new riverside path reported greater satisfaction with their neighbourhood. However, participants chose whether to use the path, and many already enjoyed outdoor activities. The researchers therefore described the result as an association, not proof that building a path would improve everyone’s wellbeing. They recommended examining users and non-users over a longer period.', 'Why do the researchers avoid a firm causal claim?', 'Users may already differ from people who do not use the path', ['No participant expressed satisfaction with the area', 'The path had not yet been built', 'Longer studies cannot examine wellbeing'], 'Người tự chọn dùng đường vốn có thể thích hoạt động ngoài trời; sự khác biệt ban đầu hạn chế kết luận nhân quả.', 'inference-and-evidence'),
  p('A company replaced its annual training lecture with short practice sessions spread across several months. Employees initially complained that the new format interrupted their schedules more often. Later, supervisors noticed fewer mistakes in the tasks covered by the sessions. The company kept the format but shortened preparation materials, acknowledging that useful training could still create avoidable demands on staff time.', 'What position did the company ultimately take?', 'Retain the effective approach while reducing its inconvenience', ['Return to lectures because practice had no effect', 'Assume all staff complaints were unjustified', 'Remove training from every work schedule'], 'Họ giữ luyện tập do giảm lỗi, đồng thời rút tài liệu để giảm gánh nặng; không phủ nhận phản hồi.', 'inference-and-evidence'),
  p('A museum’s digital reconstruction shows how a ruined hall might have looked, but uncertain features appear in a different colour. Visitors can turn those features off and compare the image with surviving evidence. The designer argues that a convincing picture should not hide the distinction between what is known and what has been added to make the scene visually complete.', 'Why are some reconstructed features coloured differently?', 'To make the limits of the evidence visible', ['To identify parts visitors are forbidden to view', 'To show that those features are certainly original', 'To make the surviving ruin appear more damaged'], 'Màu khác tách phần chưa chắc khỏi chứng cứ còn lại, tránh hình đẹp che mức độ giả định.', 'inference-and-evidence'),
  p('A town introduced free parking near independent shops, expecting higher sales. Visitor numbers increased, but several retailers reported little change in income. Interviews suggested that many drivers used the spaces before walking to offices elsewhere. The council now plans to examine visit purposes, rather than judging the scheme only by how often the parking spaces are occupied.', 'What weakness in the original evaluation became apparent?', 'Busy parking did not necessarily mean more shopping', ['Retailers could not observe any change in visitor numbers', 'Free parking made all office workers shop locally', 'The council had already measured every visitor’s purpose'], 'Bãi đông có thể do người đi làm, không đồng nghĩa mua hàng; cần xem mục đích chuyến đi.', 'inference-and-evidence'),
  p('A language-learning app rewards daily use, but some learners complete the easiest exercise simply to preserve their record. Its developers added occasional review tasks requiring earlier material to be used in a new context. They still value regular participation, while recognising that a sequence of completed days cannot by itself show whether a learner can communicate outside the app.', 'What is the reason for adding contextual review tasks?', 'To check learning beyond maintaining a daily record', ['To make regular practice irrelevant', 'To prevent learners revisiting earlier material', 'To certify every user’s exam score'], 'Chuỗi ngày hoàn thành chưa thể hiện giao tiếp thực; nhiệm vụ ngữ cảnh mới kiểm tra khả năng vận dụng.', 'inference-and-evidence'),
  p('Farmers in one region tested a crop variety that required less water but ripened later. It performed well during a dry season, although the later harvest conflicted with some farms’ existing labour arrangements. The report recommends considering local schedules alongside water savings. It does not present the variety as an automatic replacement for every crop currently grown in the region.', 'What does the report suggest about adopting the variety?', 'Its environmental benefit must be considered with practical constraints', ['Lower water use removes every farming difficulty', 'A later harvest is unsuitable on all farms', 'Existing labour arrangements cannot be changed'], 'Giống tiết kiệm nước vẫn có khó khăn thời vụ lao động; khuyến nghị xét hoàn cảnh thay vì thay thế tự động.', 'inference-and-evidence'),
  p('The library’s new catalogue groups books by broad interests rather than narrow subject labels. Some visitors discover unfamiliar titles more easily, while researchers seeking a precise reference prefer the older classification. The library has retained both search options. Staff say improving discovery should not make exact retrieval harder for users whose needs differ from those of casual browsers.', 'Why does the library keep both search methods?', 'They support different kinds of information need', ['The new catalogue contains no unfamiliar books', 'Researchers never benefit from browsing', 'Broad interests are identical to narrow classifications'], 'Khám phá ngẫu nhiên và tìm tham khảo chính xác có nhu cầu khác nhau, nên giữ hai lựa chọn.', 'inference-and-evidence'),
  p('An architect used movable screens in a learning centre so rooms could support different activities. During the first month, staff rearranged them frequently but found that sound travelled across the open areas. The design was revised to include a few fixed quiet rooms. Flexibility remained important, yet the experience showed that physical openness and adaptable use were not the same thing.', 'What lesson did the initial use reveal?', 'Adaptability also requires spaces with stable acoustic protection', ['Movable screens had made every activity impossible', 'Quiet rooms cannot be part of a flexible design', 'Sound was unaffected by the open arrangement'], 'Linh hoạt không chỉ mở không gian: cần phòng yên tĩnh cố định để giải quyết âm thanh.', 'inference-and-evidence'),
  p('A cycling campaign gave participants devices that counted their journeys. Recorded trips rose sharply, but follow-up interviews showed that some people had already cycled regularly and had only begun logging the activity. The organisers still considered the campaign encouraging, but revised their report to distinguish increased recording from genuinely new cycling that replaced travel by other means.', 'Why was the original report revised?', 'More recorded trips could partly reflect changed measurement habits', ['Interviews proved that nobody cycled regularly before', 'The devices could not record any journey', 'Every new cycling trip necessarily replaced a car journey'], 'Số ghi nhận tăng có thể vì người vốn đạp xe bắt đầu ghi, chứ không hoàn toàn hành vi mới.', 'inference-and-evidence'),
  p('An online course allowed students to watch lectures at any time, which improved access for people with irregular work hours. Completion rates nevertheless remained low. Interviews revealed that several learners missed having someone respond to questions promptly. The provider added scheduled discussion sessions without removing the recordings, treating access and support as separate requirements rather than assuming convenience would solve both.', 'What does the provider’s response imply?', 'Flexible access alone was insufficient for some learners', ['Recordings were useless to people with irregular hours', 'All learners wanted identical schedules', 'Discussion sessions were intended to replace every lecture'], 'Video thuận tiện nhưng thiếu phản hồi; bổ sung thảo luận giữ tính linh hoạt và thêm hỗ trợ.', 'inference-and-evidence'),
  p('A furniture maker promoted a chair as environmentally preferable because its parts could be replaced separately. Reviewers welcomed the design but asked whether spare parts would remain available in future years. They argued that theoretical repairability has limited value if owners cannot obtain the components when needed. The company then published a support commitment alongside its original claim.', 'What concern did the reviewers raise?', 'Repairable design depends on continued access to replacement parts', ['Separate components always make furniture less durable', 'Owners had already been refused every repair', 'Publishing a commitment guarantees unlimited supplies forever'], 'Thiết kế sửa được cần phụ tùng thực tế dài hạn; khả năng trên lý thuyết chưa đủ.', 'inference-and-evidence'),
  p('Tour guides were asked to avoid describing a coastal village as unchanged for centuries. Although some buildings were old, residents had continually adapted their work and homes. The revised guide includes both historical features and recent developments. Its author argues that presenting a community as frozen in the past can make residents’ current lives seem less real than visitors’ expectations.', 'Why was the description of the village changed?', 'It had obscured ongoing changes in residents’ lives', ['No historical buildings existed in the village', 'Recent developments should replace every historical account', 'Residents wanted all tourism to end'], 'Cụm “không đổi nhiều thế kỷ” che việc cộng đồng liên tục thích nghi; hướng dẫn mới phản ánh cả cũ và mới.', 'inference-and-evidence'),
  p('A workplace trial reduced meetings by requiring written updates first. Staff gained uninterrupted time, but newer employees said they had lost informal opportunities to ask questions. Managers kept the written updates and added short optional check-ins. The aim was not to restore every meeting, but to preserve useful contact that had previously occurred accidentally around less useful discussion.', 'What distinction guided the revised arrangement?', 'Removing inefficient meetings need not remove valuable contact', ['All informal questions require a full meeting', 'Written updates are unsuitable for experienced employees', 'New employees prefer no contact with managers'], 'Họ tách cuộc họp kém hiệu quả khỏi cơ hội hỏi hữu ích, nên giữ cập nhật viết và thêm check-in ngắn.', 'inference-and-evidence'),
  p('A wildlife project placed nesting boxes in several parks. Boxes in quieter areas were occupied more often, but those areas also contained more suitable feeding habitat. The researchers could not determine whether quietness or food availability was more influential from this comparison alone. They plan further observations before advising councils to select sites mainly on the basis of noise levels.', 'What prevents the researchers identifying the key influence?', 'Two potentially important site features varied together', ['Every nesting box was left unoccupied', 'Food availability was identical in all parks', 'Noise levels had not differed between sites'], 'Nơi yên hơn cũng có thức ăn tốt hơn, nên hai yếu tố cùng thay đổi khiến không tách được ảnh hưởng.', 'inference-and-evidence'),
  p('The city’s annual arts survey counted attendance at formal venues but omitted free events in streets and community halls. A later neighbourhood study found substantial participation in those informal settings. The survey team expanded its definition of attendance, acknowledging that a narrow measurement could make cultural activity look scarce in areas where residents used different kinds of venue.', 'What was the limitation of the earlier survey?', 'It missed cultural participation outside formal venues', ['It counted all free events several times', 'It found that nobody attended community halls', 'Its definition had already included every setting'], 'Khảo sát bỏ sót hoạt động ở đường phố và hội trường cộng đồng, nên đánh giá thiếu tham gia văn hóa.', 'inference-and-evidence'),
  p('A retailer tested detailed product labels explaining durability and repair options. Customers appreciated the information, yet many still chose the lowest initial price. Researchers noted that this did not necessarily show indifference to durability: some households could not afford a higher payment immediately, even when a longer-lasting item might cost less over several years.', 'What interpretation do the researchers caution against?', 'Assuming a cheaper purchase means durability does not matter to the buyer', ['Believing all customers understood the labels', 'Considering the initial price when making a purchase', 'Noting that some durable items cost more upfront'], 'Hạn chế tiền trả ngay có thể buộc chọn rẻ dù vẫn coi trọng độ bền; không suy sự thờ ơ.', 'inference-and-evidence'),
  p('A school introduced peer comments on draft essays, but students initially focused on spelling rather than argument. The teacher provided a short set of questions about claims and supporting examples, then allowed writers to decide which suggestions to use. The change aimed to make peer feedback more thoughtful without transferring responsibility for the final essay from its author to the group.', 'What was the purpose of the guiding questions?', 'To direct attention towards reasoning while preserving the writer’s responsibility', ['To require every suggestion to be accepted', 'To stop students correcting any spelling error', 'To let classmates write the final essay jointly'], 'Câu hỏi hướng phản hồi vào lập luận/chứng cứ; người viết vẫn chọn và chịu trách nhiệm bài cuối.', 'inference-and-evidence'),
  p('Public seating near a shopping street was initially arranged in long rows. Observations showed that many seats remained empty while people stood nearby talking. After some benches were angled towards each other, small groups used them more often. The planner concluded that providing enough seats was only part of the issue; their arrangement also influenced whether they supported the activities already taking place.', 'What did the change in bench use suggest?', 'Seating layout mattered in addition to the number of seats', ['Residents had no interest in sitting outdoors', 'Angled benches increased the total population', 'Every long row must remain completely unused'], 'Người dân dùng ghế hơn khi dễ nói chuyện; vấn đề không chỉ là có đủ số ghế.', 'inference-and-evidence'),
  p('A company’s recruitment test asked applicants to explain how they would solve an unfamiliar practical problem. It did not require one specific solution, but assessors looked for clear reasoning and recognition of constraints. Applicants were told that changing an initial suggestion after considering new information could count as good judgement rather than a sign that the first answer had failed completely.', 'What ability does the test primarily seek?', 'Reasoning that responds sensibly to new information', ['Recall of one predetermined solution', 'Refusal to alter an initial suggestion', 'Speed without consideration of practical limits'], 'Đánh giá lý luận và biết giới hạn; điều chỉnh khi có thông tin mới có thể cho thấy phán đoán tốt.', 'inference-and-evidence'),
  p('A food market offered discounts near closing time to reduce unsold produce. Sales increased, but regular customers began delaying purchases in expectation of the discounts. The manager then limited reductions to items likely to spoil quickly. The revised approach tried to reduce genuine waste while avoiding a system that encouraged people to postpone every purchase until prices fell.', 'Why were the discounts narrowed to selected items?', 'The original approach was changing customers’ buying times', ['No discounted produce had ever been sold', 'All products spoiled immediately after opening', 'Regular customers refused to accept lower prices'], 'Khách bắt đầu đợi giảm giá, nên ưu đãi tập trung hàng dễ hỏng để giảm lãng phí mà tránh trì hoãn toàn bộ.', 'inference-and-evidence'),
  p('A regional history website includes several accounts of the same factory closure. Former workers emphasise different events, and the editor has not merged them into a single smooth narrative. Notes identify where records support or challenge details. The editor says disagreement can reveal how people experienced the change differently, provided readers can distinguish personal memory from independently documented facts.', 'Why does the website retain differing accounts?', 'Differences can illuminate distinct experiences when properly contextualised', ['Every memory is considered equally proven', 'The editor has refused to examine records', 'A single narrative could never contain any accurate fact'], 'Giữ khác biệt giúp thấy trải nghiệm riêng, nhưng có ghi chú để tách ký ức khỏi dữ kiện kiểm chứng.', 'inference-and-evidence'),
  p('A phone application gives users a daily energy score based on self-reported sleep and activity. The developers describe it as a prompt for reflection, not a medical assessment. Reviewers praised that distinction but warned that a precise number might still appear more authoritative than the underlying information warranted. They recommended showing the score’s limitations beside it rather than in a separate document.', 'What risk do the reviewers identify?', 'Numerical precision may create an exaggerated impression of reliability', ['Users never understand any limitation statement', 'The application directly measures every medical condition', 'Reflection cannot involve information about sleep'], 'Con số cụ thể có thể khiến người dùng tưởng độ tin cậy cao hơn dữ liệu tự báo thực tế.', 'inference-and-evidence'),
  p('A conservation group asked volunteers to photograph river conditions from fixed locations each month. Earlier images had been difficult to compare because people chose attractive viewpoints that changed between visits. The new method produced less varied pictures but more useful evidence of changes. Volunteers were still encouraged to take other photographs, provided those were labelled separately from the monitoring record.', 'What is gained by using fixed photographic locations?', 'More reliable comparison across visits', ['More artistic variation in every monitoring image', 'Proof that river conditions never change', 'A reason to prohibit all other photographs'], 'Vị trí cố định giảm khác biệt góc chụp, giúp so sánh thay đổi qua các tháng rõ hơn.', 'inference-and-evidence'),
  p('An evening course advertised itself as suitable for beginners but expected participants to recognise several technical terms immediately. Some learners stopped attending before asking for help. After interviews, the college added an introductory glossary and changed the first session. Staff realised that welcoming language in an advertisement was insufficient if the teaching still assumed knowledge newcomers had not yet acquired.', 'What inconsistency did the college address?', 'The course’s entry assumptions conflicted with its beginner-friendly description', ['All beginners had already mastered the technical terms', 'The advertisement had discouraged new learners from applying', 'The course had offered only introductory vocabulary'], 'Quảng cáo dành cho mới học nhưng bài đầu giả định biết thuật ngữ, nên phải sửa đầu vào giảng dạy.', 'inference-and-evidence'),
  p('A city trial placed signs estimating walking times between major stops. Some pedestrians took routes they had previously considered too far, but others questioned the estimates because the figures assumed a steady pace. The updated signs show approximate ranges and mention steep sections. Planners wanted to encourage walking without treating one traveller’s speed as a standard suitable for everyone.', 'Why were time ranges added?', 'A single estimate did not reflect different walking abilities', ['Every route had become longer during the trial', 'Nobody had changed their travel choices', 'Walking times could be measured only for steep streets'], 'Một tốc độ chuẩn không phù hợp mọi người; khoảng thời gian và ghi dốc giúp phản ánh khác biệt.', 'inference-and-evidence'),
  p('A school replaced a prize for the highest test score with separate recognition for strong performance and clear improvement. Teachers still used common assessment criteria, but compared progress with each pupil’s earlier work. The change was intended to acknowledge achievement at different starting points, not to suggest that all final results were identical or that standards no longer mattered.', 'What is the intended effect of the change?', 'Recognise progress without abandoning performance standards', ['Treat all final scores as equal', 'Remove assessment criteria from teaching', 'Reward only pupils who began with the highest marks'], 'Thêm ghi nhận cải thiện từ mức đầu, trong khi chuẩn đánh giá và thành tích cao vẫn được giữ.', 'inference-and-evidence'),
  p('Residents were asked whether they supported a new street market. Many agreed in principle, but comments raised concerns about delivery access and noise early in the morning. The organiser changed the opening hours and left a route clear for deliveries. She argued that positive responses did not mean every practical detail had already been accepted, so the comments still required attention.', 'How did the organiser interpret general support?', 'As compatible with concerns that still needed practical solutions', ['As permission to ignore all detailed comments', 'As proof that no delivery route was needed', 'As rejection of the entire market proposal'], 'Ủng hộ ý tưởng không đồng nghĩa chấp nhận mọi chi tiết; phản hồi về giờ và giao hàng vẫn cần xử lý.', 'inference-and-evidence'),
  p('A restaurant introduced an unfamiliar dish by offering a small tasting portion. Customers could then order a full meal if they wished. The chef said the approach reduced the pressure of choosing something entirely unknown. It also provided feedback before the dish became a permanent menu item, although people willing to taste it might not represent the restaurant’s whole customer base.', 'What limitation applies to the tasting feedback?', 'Voluntary tasters may differ from other customers', ['Nobody could order the complete dish', 'The chef received no response at all', 'Every customer was required to try the sample'], 'Người tự nguyện thử có thể không đại diện toàn bộ khách, dù phản hồi vẫn hữu ích.', 'inference-and-evidence'),
  p('A transport survey asked passengers what would improve their journey. Faster travel was common in written answers, but interviews revealed that uncertainty about arrival mattered more to many users. The operator began publishing clearer delay information alongside plans to improve speed. The findings suggested that a journey’s practical value depended partly on predictability, not just the number of minutes it usually took.', 'What did the interviews add to the written responses?', 'They revealed the importance of reliable expectations', ['They proved speed was irrelevant to every passenger', 'They showed that no one experienced delays', 'They replaced the need for any transport improvement'], 'Phỏng vấn làm rõ nhiều khách lo tính dự đoán thời điểm hơn chỉ tốc độ; không khẳng định tốc độ vô nghĩa.', 'inference-and-evidence'),
  p('A museum allowed visitors to handle replicas of fragile objects while originals remained protected. Some visitors initially thought the replicas were authentic. Staff therefore added visible labels explaining their purpose. The curator maintained that touch could support understanding, but only if the experience did not confuse the source of historical evidence with a modern object created to illustrate it.', 'Why was labelling the replicas important?', 'To prevent a useful activity from misleading visitors about authenticity', ['To stop all visitors learning through touch', 'To prove the originals had been created recently', 'To make fragile originals available for unrestricted handling'], 'Nhãn giữ lợi ích chạm mẫu mà không khiến khách nhầm bản sao hiện đại với vật gốc lịch sử.', 'inference-and-evidence'),
  p('A workplace introduced a common document template to make reports easier to compare. Staff welcomed the clearer headings but found that one section did not fit unusual projects. Managers kept the shared structure while allowing an explained exception. Consistency remained useful, yet the organisation recognised that forcing every case into identical boxes could remove information needed to understand meaningful differences.', 'Why were explained exceptions permitted?', 'An identical structure could conceal relevant differences between projects', ['The template had no useful headings', 'Managers wanted reports to be impossible to compare', 'Every project required an entirely new format'], 'Một số dự án khác thường không vừa mẫu; ngoại lệ có giải thích giữ thông tin quan trọng mà vẫn nhất quán.', 'inference-and-evidence'),
  p('A neighbourhood garden project invited anyone to contribute, but most meetings occurred during normal working hours. Volunteers later asked why younger residents were rarely present. An evening session attracted new participants, suggesting that apparent lack of interest had partly reflected the schedule. Organisers then alternated meeting times instead of treating one successful session as proof that evenings suited everyone.', 'What assumption was challenged by the evening session?', 'Low attendance necessarily meant low interest', ['No younger resident could attend an evening meeting', 'Working hours were convenient for every participant', 'One new session solved all scheduling difficulties'], 'Người mới tới buổi tối cho thấy lịch ban ngày là rào cản; ít tham gia không hẳn không quan tâm.', 'inference-and-evidence'),
  p('Researchers compared two versions of a safety notice. The shorter version was read more quickly, but several readers missed an important exception. A revised version used headings to separate the main action from the exception rather than simply removing words. The team concluded that reducing reading time was not a sufficient measure of clarity when readers also needed to apply the information correctly.', 'What did the comparison show about shorter notices?', 'They are not necessarily clearer in practical use', ['They always contain more exceptions', 'Reading speed cannot ever be measured', 'Headings prevent readers understanding instructions'], 'Đọc nhanh nhưng bỏ sót ngoại lệ cho thấy ngắn chưa chắc dễ áp dụng đúng; cần tổ chức thông tin.', 'inference-and-evidence'),
  p('A clothing repair event attracted people who wanted to extend the life of favourite garments. Volunteers explained which repairs were straightforward and which required specialist equipment. Organisers did not claim that every item could be rescued. They considered honest limits important because unrealistic promises might discourage future repair attempts when a difficult case could not be solved during one afternoon.', 'Why did organisers emphasise the event’s limits?', 'To avoid expectations that could undermine trust in repair', ['To persuade everyone to replace all clothing', 'To show that straightforward repairs were impossible', 'To prevent volunteers using any equipment'], 'Không hứa cứu mọi đồ giúp tránh kỳ vọng sai gây thất vọng và giảm niềm tin vào sửa chữa.', 'inference-and-evidence'),
  p('An online platform suggested books similar to those a reader had already selected. Users appreciated familiar recommendations but sometimes complained that the list became repetitive. The platform added a separate exploration option based on different subjects. It did not remove personalised suggestions, acknowledging that ease of selection and discovery of unfamiliar material could require different approaches.', 'What need does the exploration option serve?', 'Finding material beyond established preferences', ['Repeating the same list more frequently', 'Preventing readers choosing familiar subjects', 'Proving personal recommendations are always wrong'], 'Tùy chọn khám phá mở ra nội dung ngoài sở thích đã biết, vẫn giữ gợi ý cá nhân khi hữu ích.', 'inference-and-evidence'),
  p('A city planted trees along a hot pedestrian route, but the young trees provided little shade initially. Temporary shelters were added while they grew. The project manager described planting as a long-term investment rather than an immediate solution. Residents would therefore benefit from both future canopy cover and practical protection during the years before that cover developed.', 'Why were temporary shelters included?', 'Young trees could not yet deliver the full intended benefit', ['The city expected every tree to die', 'Mature tree cover had already blocked the route', 'Shelters eliminated the need for long-term planting'], 'Cây non chưa tạo đủ bóng nên cần bảo vệ tạm, bổ sung chứ không thay thế mục tiêu dài hạn.', 'inference-and-evidence'),
  p('A group preparing a local-history display asked residents for photographs but also recorded where and when each image had been taken. Some attractive pictures could not be dated confidently and were labelled accordingly. The organisers said an uncertain image could still be shown, provided its appeal did not lead viewers to assume that every detail had been independently verified.', 'What principle guides the use of uncertain photographs?', 'They may be useful if uncertainty is made clear', ['Attractive images are automatically reliable evidence', 'Only photographs with no context should be displayed', 'Labelling uncertainty makes all historical displays pointless'], 'Ảnh chưa định thời chắc vẫn có ích nếu ghi rõ giới hạn, không để vẻ đẹp tạo ấn tượng đã kiểm chứng.', 'inference-and-evidence'),
  p('A new office booking system showed that some desks were rarely reserved. Management considered removing them, but observations found employees used those desks for brief collaborative tasks that did not require formal booking. The team added a separate category for casual use before changing the layout. It recognised that absence from a record was not always evidence that a resource was unused.', 'Why was removal delayed?', 'The booking data omitted a genuine type of use', ['Every employee reserved every desk daily', 'The office had no collaborative work', 'Observations confirmed the desks were never used'], 'Việc dùng nhanh không đặt chỗ bị bỏ khỏi dữ liệu; ít đặt chưa chứng minh ít sử dụng.', 'inference-and-evidence'),
  p('A volunteer project initially assigned the same number of tasks to each member. Some tasks required far more preparation than others, and resentment developed despite the equal count. The coordinator began discussing estimated effort and individual availability instead. The revised arrangement remained transparent, but fairness was assessed through practical demands rather than assuming identical numbers meant identical contributions.', 'What was wrong with the initial allocation method?', 'Equal task counts did not represent equal effort', ['No tasks needed any preparation', 'Members had identical availability and skills', 'Transparency prevented volunteers from helping'], 'Số việc bằng nhau nhưng yêu cầu chuẩn bị khác nhau, nên mức đóng góp không thực sự ngang nhau.', 'inference-and-evidence'),
  p('A walking app estimated distance accurately but gave routes through private courtyards that looked like public shortcuts on a map. The developer added a way for local users to report access restrictions and checked reports before changing routes. The issue showed that precise measurement of distance did not guarantee that a suggested journey was legally or practically available to the traveller.', 'What broader point does the routing problem illustrate?', 'Accurate figures do not guarantee appropriate recommendations', ['Short routes are always through private land', 'Local reports should be accepted without checking', 'Distance cannot be measured for public streets'], 'Đo khoảng cách đúng vẫn có thể khuyên đường không được đi; cần thêm dữ kiện quyền tiếp cận.', 'inference-and-evidence'),
];
const c1: ReadingProbe[] = [
  p('Comparing cities by the total area of green space can conceal considerable differences in everyday access. A large reserve beyond an expensive transport link may raise a city’s score while doing little for residents without cars. Conversely, a network of modest shaded spaces may support frequent use without appearing impressive in aggregate statistics. The author therefore proposes supplementing area measures with information about location, accessibility and use, rather than abandoning quantitative comparison altogether.', 'Which approach does the author advocate?', 'Retain area measures but assess practical access alongside them', ['Replace all quantitative comparison with personal impressions', 'Judge a city solely by its largest reserve', 'Assume small spaces always outperform large reserves'], 'Tác giả đề nghị bổ sung vị trí/tiếp cận/sử dụng cho chỉ số diện tích, không bỏ đo lường hoàn toàn.', 'critical-reading'),
  p('A recommendation system can become more confident without becoming more informative. When users mainly see material selected from their previous choices, their subsequent behaviour may confirm the pattern that shaped the selection in the first place. The resulting agreement looks like strong evidence of preference, although alternatives were rarely visible. An audit should consequently examine the opportunities users were offered, not merely the choices recorded after those opportunities had already been filtered.', 'What is the central problem identified?', 'Observed choices may reinforce preferences partly created by restricted exposure', ['Recommendation systems cannot record any choice accurately', 'Users always prefer material they have never encountered', 'Confidence proves that alternative opportunities were unnecessary'], 'Hệ thống lọc cơ hội rồi dùng lựa chọn trong phạm vi lọc để xác nhận sở thích, tạo vòng tự củng cố.', 'critical-reading'),
  p('The restored theatre is frequently praised for recovering its original appearance, yet that description overlooks substantial conjecture. Surviving drawings establish the arrangement of the main spaces, while details of colour and decoration were inferred from comparable buildings. This need not invalidate the restoration as a usable cultural venue. It does, however, make the phrase “exact reconstruction” inappropriate, unless visitors are told which features derive from direct evidence and which reflect a reasoned modern interpretation.', 'How does the writer regard the restoration?', 'Useful, but inaccurately described if inferred details are presented as exact', ['Worthless because any inference makes a building unusable', 'Fully documented in every decorative detail', 'Acceptable only if all modern features are removed'], 'Tác giả không phủ nhận công dụng; phản đối gọi “chính xác” khi nhiều chi tiết suy đoán chưa được phân biệt.', 'critical-reading'),
  p('Uniform crops can simplify harvesting and commercial grading, but their apparent efficiency depends on the risks included in the calculation. If a shared vulnerability exposes an entire planting to disease, a system optimised for an ordinary season may prove fragile under stress. Advocates of greater diversity are therefore not necessarily rejecting productivity; they are questioning whether productivity measured over a narrow period adequately represents the reliability of food production over less predictable conditions.', 'What distinction underlies the argument?', 'Short-term efficiency may differ from resilience across uncertain conditions', ['Commercial grading eliminates every disease risk', 'Crop diversity necessarily requires abandoning productivity', 'Reliable food production can be assessed only in one ordinary season'], 'Lập luận tách hiệu quả mùa bình thường khỏi độ bền trước biến động, không đánh đồng đa dạng với bỏ năng suất.', 'critical-reading'),
  p('A language programme’s success should not be inferred solely from participants becoming accustomed to its test format. Familiarity can improve measured performance even when the ability to explain unfamiliar ideas remains largely unchanged. This does not make testing useless: consistent tasks can reveal progress in defined skills. The difficulty arises when a narrow result is treated as evidence of unrestricted communicative competence, without checking whether learners can transfer what they have practised to situations unlike those used in assessment.', 'What claim does the passage challenge?', 'Better performance on a familiar test necessarily shows broad communication improvement', ['Consistent assessment tasks can never reveal useful progress', 'Transfer to unfamiliar situations has no relevance to language ability', 'All learners’ measured results are deliberately fabricated'], 'Điểm tốt do quen dạng chưa chắc khả năng giao tiếp rộng; đoạn vẫn công nhận ích lợi kiểm tra kỹ năng xác định.', 'critical-reading'),
  p('Popular accounts of research sometimes turn a qualified conclusion into a striking recommendation. The transformation may occur gradually: a finding described as suggestive in a paper becomes promising in a press summary, then decisive in a headline. Each step appears small, yet the final message can imply a certainty the original investigators explicitly withheld. Improving communication therefore requires attention to the chain of retelling, not simply asking scientists to write a less technical first account.', 'Why does the writer focus on the chain of retelling?', 'Certainty may be exaggerated incrementally after the original account', ['Scientists always intend headlines to be decisive', 'Technical vocabulary is the only source of distortion', 'Press summaries inevitably preserve every qualification'], 'Mức chắc chắn bị tăng dần qua nhiều lần tóm tắt; lỗi không chỉ nằm ở văn bản khoa học ban đầu.', 'critical-reading'),
  p('Interactive museum displays are often evaluated by how long visitors remain engaged, but attention is not identical to understanding. A visitor may spend several minutes manipulating a device without recognising the historical relationship it is intended to illustrate. This observation is not an argument against interaction. Rather, it suggests that evaluation should examine what visitors can explain afterwards, while allowing that curiosity and enjoyment may be worthwhile outcomes distinct from acquisition of the specific knowledge targeted by the exhibit.', 'What evaluation principle is proposed?', 'Distinguish engagement from intended learning while recognising other benefits', ['Treat enjoyment as evidence that all historical relationships were understood', 'Remove interactive displays whenever visitors remain interested', 'Measure understanding only through time spent at a device'], 'Cần phân biệt chú ý, hiểu mục tiêu và lợi ích tò mò/vui thích, không phủ nhận tương tác.', 'critical-reading'),
  p('Remittances are measurable transfers, whereas the social costs of migration are less readily expressed in comparable units. An account focused only on money may therefore show a household becoming better off while overlooking changes in unpaid care, emotional support or decision-making. The point is not that financial gains are unreal. It is that a readily counted benefit can dominate an assessment because other consequences are harder to quantify, rather than because those consequences are necessarily less important to the people involved.', 'What limitation of a money-focused assessment is highlighted?', 'Ease of measurement may give financial effects disproportionate weight', ['Remittances cannot provide any genuine household benefit', 'All social consequences can be expressed in the same currency', 'Migration always reduces every form of emotional support'], 'Lợi ích tiền có thật nhưng dễ đếm nên có thể lấn át hệ quả chăm sóc/tinh thần khó lượng hóa.', 'critical-reading'),
  p('An adaptable building is sometimes described as sustainable because it can accommodate future uses. That claim remains conditional: conversion may require substantial materials, and the imagined future use may never occur. Nevertheless, rigid designs can impose their own costs when needs change. The appropriate comparison is consequently between plausible lifecycles, with their uncertainties stated, rather than between a flexible design treated as permanently reusable and a conventional one assumed to become obsolete immediately.', 'Which comparison does the passage consider appropriate?', 'Realistic lifecycle scenarios that acknowledge uncertainty on both sides', ['Guaranteed permanent reuse versus immediate conventional obsolescence', 'Initial appearance without any consideration of later use', 'Only the conversion costs of the adaptable design'], 'Đoạn yêu cầu so kịch bản vòng đời hợp lý cho cả hai, không ưu ái bằng giả định cực đoan.', 'critical-reading'),
  p('A subsidy for efficient appliances may increase purchases among households already able to replace their equipment, while leaving lower-income households dependent on older products. Its environmental effect can still be positive, but describing the policy as equally accessible would be misleading. Evaluating uptake requires more than counting subsidised sales: investigators need to ask who could afford the remaining price and whether the scheme changed their decision, rather than merely subsidising a purchase they would have made anyway.', 'What additional evidence is needed to assess the subsidy?', 'Who could use it and whether it altered an otherwise expected purchase', ['Only the number of products displayed in shops', 'Proof that every efficient appliance costs the same', 'A guarantee that all recipients had low incomes'], 'Cần xem khả năng trả phần còn lại và quyết định có thực sự thay đổi, thay vì chỉ đếm doanh số trợ cấp.', 'critical-reading'),
  p('When organisations celebrate employees who stay late, they may unintentionally reward the visibility of commitment rather than its quality. Workers with caring responsibilities can contribute effectively within ordinary hours yet appear less devoted under that convention. Replacing it with a simple output count is not necessarily sufficient, since valuable coordination may also be difficult to count. A fairer assessment would examine the nature of the contribution and the conditions under which it was made, instead of relying on whichever proxy is easiest to observe.', 'What does the passage suggest about assessing commitment?', 'Neither visible hours nor a simple output count necessarily captures contribution fairly', ['Late working always demonstrates poor performance', 'Caring responsibilities remove any need to assess work', 'The easiest observable proxy is usually the fairest'], 'Cả giờ ở lại lẫn số đầu ra đơn giản đều có thể bỏ sót đóng góp; cần xét bản chất công việc và điều kiện.', 'critical-reading'),
  p('Written models of spoken answers can illustrate organisation and vocabulary, but they cannot establish how a learner delivers those words. Reading a polished response may conceal hesitation, inappropriate stress or difficulty responding spontaneously to a follow-up question. Such models remain useful when treated as examples of idea development. Their value is overstated when the quality of the text is presented as a certified speaking score, detached from the performance that a speaking assessment actually requires.', 'What is the passage’s main qualification?', 'A strong written model does not certify spoken performance', ['Written examples provide no information about vocabulary', 'Every spontaneous follow-up question is inappropriate', 'Speaking assessment is concerned only with written organisation'], 'Mẫu viết minh họa ý/từ, nhưng không chứng nhận độ trôi chảy, trọng âm hay ứng đáp khi nói.', 'critical-reading'),
  p('A transport network with several alternative routes may appear inefficient when judged only by normal-day occupancy. Spare capacity carries a cost, but it can also prevent one disruption from isolating an entire area. Decisions about redundancy therefore involve the frequency and consequence of failure, not merely the average utilisation of each route. The least-used connection may have considerable public value precisely because it becomes important only under conditions that routine performance figures rarely capture.', 'Why might a rarely used connection still be valuable?', 'It can protect access during disruptions missed by normal-day measures', ['Low occupancy proves that its running costs are zero', 'Alternative routes prevent every possible transport failure', 'Routine utilisation fully measures the consequences of isolation'], 'Tuyến ít dùng có giá trị dự phòng khi gián đoạn, điều mà số sử dụng ngày thường không thể hiện.', 'critical-reading'),
  p('Digital archives can make surviving records widely accessible, yet the impression of abundance may obscure the history of selection. Materials first had to be created, preserved and chosen for digitisation; many voices were lost at one or more of those stages. A searchable collection is therefore not a neutral sample of everything that once existed. Researchers should ask how it was assembled, while recognising that imperfect representation does not make the surviving evidence unusable.', 'What caution is given about digital archives?', 'Easy access does not remove earlier biases in what survived and was selected', ['Digitisation makes every surviving record historically worthless', 'Searchable collections necessarily include all past voices', 'Researchers should avoid asking how collections were assembled'], 'Tạo lập, lưu giữ và số hóa đều chọn lọc; lượng nhiều/dễ tìm chưa đồng nghĩa đại diện trung lập.', 'critical-reading'),
  p('An energy project’s annual output can look impressive even when production and demand rarely peak together. Storage or connections to other sources may address that mismatch, but their costs and losses need to be included in comparisons. The argument does not dismiss renewable generation. It rejects the assumption that a yearly total alone reveals how reliably a particular project can meet local needs at the times those needs arise.', 'What is missing from an annual-output comparison?', 'How production timing matches demand and the cost of bridging gaps', ['Any evidence that the project produces energy at all', 'The claim that renewable generation must be rejected', 'Proof that storage has no costs or losses'], 'Tổng năm bỏ qua thời điểm cung-cầu và chi phí bù chênh lệch; không phải phủ nhận năng lượng tái tạo.', 'critical-reading'),
  p('Repair services are frequently presented as an antidote to rapid replacement, but their viability depends partly on how products are designed and priced. A skilled repairer cannot make a sealed component accessible without additional labour, nor persuade every owner to repair an item when a new version costs less. Promoting repair therefore requires attention to incentives and design, not merely urging consumers to be more responsible after a product has already failed.', 'What does the writer argue is necessary to promote repair?', 'Address product design and economic incentives as well as consumer choices', ['Expect repairers to overcome all design barriers without cost', 'Treat a lower replacement price as irrelevant to owners', 'Focus exclusively on moral appeals after products fail'], 'Sửa chữa phụ thuộc thiết kế và giá tương đối, nên cần thay cấu trúc khuyến khích chứ không chỉ kêu gọi trách nhiệm.', 'critical-reading'),
  p('A publication that corrects an error visibly may seem less infallible than one that leaves it untouched. Yet the correction offers evidence of a process capable of responding to new information. This is not a reason to excuse careless reporting: frequent avoidable errors can still undermine confidence. The relevant distinction is between trust grounded in an appearance of permanent certainty and trust grounded in transparent methods, proportionate claims and accountable revision when those claims prove inaccurate.', 'Which basis for trust does the passage favour?', 'Transparent and accountable correction rather than an appearance of infallibility', ['Frequent errors as automatic proof of journalistic quality', 'Leaving mistakes untouched to maintain certainty', 'Avoiding all claims that could ever be revised'], 'Đoạn ưu tiên phương pháp minh bạch và sửa sai có trách nhiệm, vẫn phê phán lỗi tránh được.', 'critical-reading'),
  p('An open consultation meeting does not automatically produce a representative view. Attendance reflects available time, confidence in public speaking and awareness that the meeting exists. Those present can provide important knowledge, but their participation should not erase the circumstances of absent residents. Supplementary interviews and varied response channels may broaden the evidence. They cannot guarantee perfect representation, yet they make it less defensible to equate the loudest visible agreement with the preferences of an entire neighbourhood.', 'What assumption does the passage reject?', 'An open meeting’s visible agreement necessarily represents all residents', ['People who attend meetings cannot provide useful knowledge', 'Additional response channels guarantee perfect representation', 'Absent residents always oppose the proposal discussed'], 'Cơ hội dự họp bị chi phối thời gian, tự tin và thông tin, nên tiếng nói hiện diện không đại diện chắc toàn khu.', 'critical-reading'),
  p('Limiting visitors to a fragile destination can protect the environment while creating a separate question about allocation. If scarce places are distributed only through high prices, access may depend more on wealth than interest or need. A ballot offers a different principle but can introduce uncertainty for people arranging travel. The existence of an environmental limit therefore does not settle how that limit should be administered; effectiveness and fairness require related but distinct judgements.', 'What distinction is central to the passage?', 'Justifying a visitor limit differs from deciding how access should be allocated', ['Environmental protection eliminates every allocation problem', 'High prices and ballots have identical consequences', 'Uncertain access always causes more environmental damage'], 'Có lý do môi trường cho giới hạn chưa quyết định cách chia suất; hiệu quả và công bằng là hai phán đoán liên quan.', 'critical-reading'),
  p('Neighbourhood boundaries on maps often look more definite than residents’ descriptions of where they belong. Administrative lines serve useful purposes, such as assigning services, but social identities may overlap or shift with routes, workplaces and relationships. Treating the map as mistaken would overlook its practical function. Treating it as a complete account of local experience would be equally limiting. The value of each description depends on the question for which it is being used.', 'How should mapped boundaries be interpreted?', 'As useful for certain purposes but incomplete descriptions of lived identity', ['As always incorrect because residents disagree', 'As definitive accounts of every social relationship', 'As unnecessary for assigning any public service'], 'Ranh giới hành chính hữu ích cho dịch vụ nhưng không bao trọn cảm nhận thuộc về và quan hệ thực tế.', 'critical-reading'),
  p('Statistics on vacant housing can suggest a straightforward solution to a shortage, but the category may combine properties awaiting repair, homes in places without local demand and units withheld from use for financial reasons. These conditions call for different responses. The author does not deny that some vacancies are avoidable; she questions a policy that treats every unoccupied dwelling as immediately available merely because the aggregate number appears sufficient to house those currently looking for accommodation.', 'What is the author’s main objection?', 'The vacancy total combines conditions requiring different practical responses', ['No vacant property could ever help address a shortage', 'All unoccupied homes are intentionally withheld for profit', 'Housing demand is identical in every location'], 'Số trống gộp nhiều nguyên nhân, không phải mọi căn sẵn dùng; cần giải pháp theo loại thay vì dựa tổng.', 'critical-reading'),
  p('Offering every student identical assistance may appear impartial, yet it can preserve unequal opportunities to use that assistance. A learner with reliable equipment can benefit from an online resource that another can access only briefly on a borrowed device. Differentiated support is not necessarily a lowering of expectations. It can be a way of maintaining common academic goals while addressing unequal conditions, provided the additional help is related to genuine barriers rather than assumptions about a group’s ability.', 'How is differentiated support justified here?', 'It can sustain common goals by addressing unequal access conditions', ['It requires abandoning all common academic expectations', 'It assumes every member of a group has identical ability', 'It is impartial only when equipment differences are ignored'], 'Hỗ trợ khác nhau có thể giữ mục tiêu chung bằng cách gỡ rào cản tiếp cận, không phải hạ chuẩn.', 'critical-reading'),
  p('The distance travelled by food is an intuitively attractive environmental measure, but it is only one part of the production chain. Transport mode, storage requirements and farming inputs may alter the comparison substantially. A nearby product is not therefore inferior, nor is proximity irrelevant. The caution is against allowing an easily understood distance figure to stand in for a complete assessment, particularly when the information needed to evaluate other stages has not been considered.', 'What judgement about food transport does the passage support?', 'Food distance is relevant but insufficient for an overall environmental judgement', ['Nearby products are generally worse for the environment', 'Transport distance has no environmental significance', 'Other production stages are already included in any distance figure'], 'Độ xa có liên quan nhưng còn phương tiện, lưu trữ, đầu vào canh tác; không đủ thay toàn đánh giá.', 'critical-reading'),
  p('An advertisement can be remembered without persuading its audience. A striking image may leave viewers able to describe the scene while unable to identify the product, and repeated exposure may create familiarity without changing purchasing behaviour. Evaluating a campaign by recall alone therefore risks confusing an intermediate response with the intended outcome. Recall can remain informative, but the relationship between attention, recognition and action must be investigated rather than assumed to follow automatically from a memorable presentation.', 'Why is recall alone an inadequate campaign measure?', 'Remembering content does not necessarily produce the intended purchasing effect', ['Memorable images always prevent product recognition', 'Repeated exposure can never create familiarity', 'Audience attention is unrelated to any possible outcome'], 'Nhớ cảnh hoặc thấy quen chưa chắc mua; recall là phản ứng trung gian, cần kiểm tra quan hệ với hành động.', 'critical-reading'),
  p('People who keep detailed wellbeing diaries may become more attentive to habits that affect how they feel. If their reports improve, however, the diary itself is not the only possible explanation. Participants may also change routines because they know they are being observed, or record experiences differently after learning the categories. A useful study would consider these alternatives. The aim is not to dismiss self-reporting, but to avoid attributing every favourable change to a single feature of the intervention.', 'What caution is needed when interpreting improvement?', 'Several changes associated with participation may explain the reports', ['Wellbeing diaries cannot contain any useful information', 'Participants’ routines necessarily remain unchanged', 'A favourable report proves the diary’s categories were accurate'], 'Quan sát bản thân, đổi thói quen hoặc cách ghi có thể cùng ảnh hưởng; không quy hết tác dụng cho một yếu tố.', 'critical-reading'),
  p('Calling a material recycled describes its origin, not every consequence of using it. Processing may require energy, and the resulting product may differ in durability or future recoverability. These considerations do not negate the value of recycling; they determine whether a particular use delivers the expected benefit. Comparisons should therefore consider the alternative product and its lifecycle, rather than treating the label as a complete environmental argument independent of how the material is processed and eventually used.', 'What role should the recycled label have in evaluation?', 'Provide relevant information without replacing lifecycle comparison', ['Guarantee that every use has the same environmental benefit', 'Prove the material will always be less durable', 'Make processing energy irrelevant to the assessment'], 'Nguồn tái chế là một thông tin, vẫn cần xem xử lý, độ bền, vòng đời và sản phẩm thay thế.', 'critical-reading'),
  p('A public artwork described as co-created may still leave substantial decisions with a single artist or funding body. Residents might select colours while having no influence over the theme, location or maintenance plan. This does not make their participation meaningless, but the description should reflect its actual scope. Celebrating involvement without explaining which decisions remained open can create expectations of ownership that the project’s governing arrangements were never designed to recognise.', 'What should the term co-created make clear?', 'The decisions participants could genuinely influence', ['That every resident controlled every stage equally', 'That selecting colours has no possible value', 'That maintenance is always the artist’s private concern'], 'Cần nói rõ phạm vi ảnh hưởng; tham gia chọn màu có giá trị nhưng chưa đồng nghĩa quyền mọi quyết định.', 'critical-reading'),
  p('A creative assignment can invite experimentation while its marking scheme quietly rewards conformity. If pupils are told to develop original solutions but see the highest marks awarded to work resembling the teacher’s example, the incentive is contradictory. Examples are still useful for clarifying technique. The problem emerges when an illustrative model becomes an unannounced standard of acceptable imagination, narrowing the range of responses that the task ostensibly encouraged pupils to explore.', 'Which contradiction is identified?', 'Originality is encouraged verbally but resemblance to a model is rewarded', ['Examples make all technical instruction impossible', 'Every pupil receives the same mark regardless of work', 'The assignment explicitly forbids any experimentation'], 'Nhiệm vụ mời sáng tạo nhưng chấm cao bài giống mẫu tạo khuyến khích ngược; không phủ nhận ích lợi dạy kỹ thuật.', 'critical-reading'),
  p('Volunteer hours are easy to report, whereas effective coordination is harder to display. A project may therefore celebrate the number of participants while underestimating the paid planning that makes their contribution useful. Removing that support to appear more community-led can leave volunteers confused or overburdened. Genuine community participation need not exclude professional organisation; the two may be complementary, with good coordination reducing the demands placed on people who offer limited time rather than increasing institutional control over them.', 'How does the passage view professional coordination?', 'It can enable meaningful volunteering rather than oppose community participation', ['It inevitably turns volunteers into paid employees', 'It is valuable only if participation numbers decline', 'It should be removed whenever volunteer hours can be counted'], 'Tổ chức chuyên nghiệp có thể giúp đóng góp hiệu quả và giảm gánh nặng, không nhất thiết đối nghịch cộng đồng.', 'critical-reading'),
  p('An unfamiliar accent may require a listener to adjust, but that adjustment should not be confused with evidence that the speaker’s language is defective. Intelligibility depends partly on listener experience and the communicative setting, as well as on pronunciation. This does not imply that every utterance is equally understandable. It means that assessment should identify specific communication difficulties rather than use resemblance to one preferred accent as a shortcut for judging the speaker’s overall ability.', 'What assessment shortcut is criticised?', 'Treating similarity to a preferred accent as a measure of overall ability', ['Investigating specific communication difficulties', 'Recognising that some utterances are harder to understand', 'Considering the listener’s previous language experience'], 'Đoạn phản đối dùng giống giọng chuẩn ưa thích làm thước đo năng lực, thay vì xem khó hiểu cụ thể.', 'critical-reading'),
  p('Remote working can reduce commuting without necessarily eliminating travel. Some households move farther from an office once daily attendance is no longer required, making occasional journeys longer. Others use the saved time for additional trips. These possibilities complicate estimates based only on cancelled commutes. The argument is not that remote work has no transport benefit, but that behavioural responses should be included before a simple reduction in office attendance is translated into an equally simple claim about overall travel.', 'What must be considered in estimating transport effects?', 'Changes in behaviour beyond the cancelled daily commute', ['The assumption that every household moves farther away', 'Only the number of office desks remaining empty', 'Proof that remote work never saves a journey'], 'Cần tính chuyển chỗ ở, chuyến đi mới và hành vi khác; bỏ chuyến đi làm chưa bằng giảm tổng tương ứng.', 'critical-reading'),
  p('An automated decision may be consistent in applying a rule while the rule itself remains poorly suited to the case. Consistency is therefore not sufficient evidence of fairness. An explanation should show which information was used and why it mattered, but an understandable explanation does not automatically justify the underlying criterion. Accountability requires a route for examining both the application of the rule and the reasons for selecting it, rather than treating mechanical uniformity as an answer to every challenge.', 'What distinction does the passage emphasise?', 'Consistent application differs from justification of the rule itself', ['An understandable explanation guarantees a fair criterion', 'Uniform decisions cannot ever be challenged', 'Automation makes the choice of information irrelevant'], 'Áp quy tắc nhất quán không chứng minh quy tắc công bằng; cần kiểm tra cả áp dụng và lý do chọn tiêu chí.', 'critical-reading'),
  p('Scenarios about future work are useful when they expose choices, but misleading when presented as forecasts with unwarranted certainty. A scenario may assume a particular pace of technological adoption so that its consequences can be explored. Readers who mistake that assumption for a prediction may overlook alternatives the exercise was intended to illuminate. The practical value lies in testing decisions against several plausible conditions, not in selecting the most vivid narrative and treating it as an inevitable destination.', 'What is the appropriate use of future scenarios?', 'Explore decisions under different plausible conditions', ['Identify the one vivid account that must occur', 'Treat every modelling assumption as an established prediction', 'Avoid considering consequences of technological adoption'], 'Kịch bản dùng thử quyết định trong nhiều điều kiện khả dĩ, không phải dự báo chắc hoặc tương lai tất yếu.', 'critical-reading'),
  p('Wildlife tourism can finance habitat protection while also introducing disturbance. The existence of conservation income does not settle whether the scale or timing of visits is appropriate. Conversely, evidence of some disturbance does not show that every visit should cease regardless of consequence. Management must examine both effects and consider less intrusive arrangements. The decision is complicated precisely because a source of support may also create pressure on the resource it is intended to help preserve.', 'Why is the management decision complex?', 'The same activity may provide support and create environmental pressure', ['Conservation income always prevents disturbance', 'Any disturbance proves all visits have identical effects', 'Tourism funding has no possible connection with habitat protection'], 'Du lịch có thể đồng thời tài trợ bảo tồn và gây xáo trộn, nên phải xét hai phía và cách tổ chức.', 'critical-reading'),
  p('A correct answer in a multiple-choice test may reflect knowledge, elimination of implausible alternatives or chance. Across well-designed tasks, scores can still provide useful evidence, but one response should not be interpreted as a complete account of the reasoning behind it. Asking learners to explain selected answers can reveal misconceptions hidden by the score. Such explanation supplements the efficient format rather than proving that multiple-choice assessment is intrinsically incapable of measuring anything worthwhile.', 'What role is suggested for answer explanations?', 'Reveal reasoning that a correct selection alone may not show', ['Demonstrate that all correct choices are random', 'Replace every efficient assessment format permanently', 'Confirm that a single answer fully represents understanding'], 'Giải thích bổ sung làm lộ cách lý luận/phần hiểu sai mà chọn đúng có thể che; không phủ nhận trắc nghiệm.', 'critical-reading'),
  p('An archaeological display dominated by complete objects can imply that the past survives mainly in recognisable forms. In excavation, however, fragments and traces may provide the stronger evidence, particularly when their original positions are recorded carefully. Attractive presentation is compatible with accuracy, but the curator must explain why an unimpressive remnant matters. Otherwise, selection for visual appeal can make visitors confuse the objects easiest to admire with the evidence most important for understanding how people once lived.', 'What risk arises from selecting mainly complete objects?', 'Visual appeal may be mistaken for evidential importance', ['Fragments can never provide reliable historical evidence', 'Accurate displays cannot also be attractive', 'Original excavation positions have no interpretive value'], 'Hiện vật đẹp/nguyên có thể khiến khách tưởng bằng chứng quan trọng nhất, bỏ vai trò mảnh và bối cảnh khai quật.', 'critical-reading'),
  p('A frequently cited article is clearly influential, but influence is not identical to accuracy. Citations may arise because a work supplies a convenient method, represents a position being challenged or is already well known. Counting them can help locate a debate without settling which claims within that debate are best supported. A responsible reader therefore uses prominence as a route into the literature, then examines the arguments and evidence rather than treating visibility as an automatic endorsement.', 'How should citation prominence be used?', 'As a starting point for investigation rather than proof of accuracy', ['As a guarantee that every claim is endorsed', 'As evidence that criticism of the article is impossible', 'As a reason to avoid reading its argument'], 'Nhiều trích dẫn cho thấy ảnh hưởng, có thể cả vì bị phản bác; nên dùng làm điểm vào rồi xem chứng cứ.', 'critical-reading'),
  p('A service receiving fewer complaints may have improved, but the decline can also reflect difficulty accessing the complaints process or a belief that reporting achieves nothing. Complaint totals are therefore ambiguous without information about users’ willingness and ability to respond. This does not make feedback useless. It means that silence should not be claimed as satisfaction merely because dissatisfaction has ceased to appear in the channel an organisation finds easiest to monitor.', 'What interpretation should be avoided?', 'Assuming fewer recorded complaints necessarily means greater satisfaction', ['Considering whether the reporting process is accessible', 'Using complaints as one source of service information', 'Investigating why people may stop reporting problems'], 'Ít khiếu nại có thể do khó báo hoặc hết tin báo có ích, nên im lặng chưa chắc hài lòng.', 'critical-reading'),
  p('Removing an admission fee can widen access to a cultural venue, yet cost is not the only barrier to attendance. Opening hours, transport, confidence and whether visitors feel represented may continue to shape participation. A free venue should therefore not assume that a modest increase in visits exhausts its potential audience. Equally, limited uptake does not prove the fee change was pointless; it may reveal additional obstacles that become visible once the financial one has been reduced.', 'How should limited uptake after free admission be interpreted?', 'As potentially revealing remaining barriers rather than automatically disproving the change’s value', ['As proof that admission costs never affect access', 'As evidence that the potential audience is fully reached', 'As a guarantee that all non-visitors dislike the venue'], 'Giảm giá gỡ một rào cản; tham gia còn ít có thể do rào cản khác, không tự chứng minh thay đổi vô ích.', 'critical-reading'),
  p('A device may remain physically sound while losing practical usefulness when software support ends. Describing durability solely through the strength of its casing therefore overlooks dependence on updates and compatible services. This need not require indefinite support for every product, but advertised longevity should state the relevant commitments. Otherwise, consumers may interpret a claim about material resilience as a promise of continued function that the wider technical system is not designed to fulfil.', 'What should claims of device longevity clarify?', 'The software and service support needed for continued practical use', ['Only whether the casing can withstand physical damage', 'That every product will receive indefinite support', 'That ending updates always destroys the hardware immediately'], 'Độ bền vỏ chưa bảo đảm hữu dụng nếu hết cập nhật/tương thích; cam kết tuổi thọ cần nói hỗ trợ liên quan.', 'critical-reading'),
];
const groups: [Cefr, number[], ReadingProbe[]][] = [['A2', [3,3.5,4], a2], ['B1', [4.5,5,5.5], b1], ['B2', [6,6.5,7], b2], ['C1', [7.5,8], c1]];
export const expandedReadingPlacementItems: (PlacementItem & { source: 'ai'; quality: 'ai-unreviewed' })[] = groups.flatMap(([cefr,bands,probes],groupIndex)=>probes.map((probe,index)=>{
  const choices=[probe.answer,...probe.distractors], shift=index%4,band=bands[index%bands.length]!;
  return { id: `fresh-x3-p-r-${String(groupIndex*40+index+1).padStart(3,'0')}`,skill:'reading',text:probe.text,question:probe.question,options:[...choices.slice(shift),...choices.slice(0,shift)],answer:probe.answer,explanation:probe.explanation,band,cefr,difficulty:(band-5)*1.2,subskill:probe.subskill,source:'ai',quality:'ai-unreviewed' };
}));
